package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.sail.lmdb.LmdbQueryMemoryManager;
import org.junit.jupiter.api.Test;

/** Retained directory capacity remains charged after the entries occupying it are released. */
class NativeOptionalRegistryCapacityTest {
	private static final int ENTRIES = 128;
	private static final long BUDGET = 1L << 20;

	@Test
	void closedChildScopesKeepTheirRetainedDirectoryCapacityAccounted() {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(BUDGET, BUDGET);
		try (var ledger = manager.openQuery(); var registry = new OptionalMaterialization(new Object(), ledger)) {
			long baseline = manager.usedBytes();
			List<OptionalEvaluationIdentity> children = new ArrayList<>();
			try {
				for (int i = 0; i < ENTRIES; i++) {
					children.add(registry.child(registry.root()));
				}
			} finally {
				children.forEach(OptionalEvaluationIdentity::close);
			}
			assertThat(registry.metrics().activeScopes()).isEqualTo(1);
			assertThat(manager.usedBytes()).as("the live registry retains the enlarged scope directory")
					.isGreaterThan(baseline);
		}
		assertThat(manager.usedBytes()).isZero();
	}

	@Test
	void closedMandatoryEntriesKeepTheirRetainedDirectoryCapacityAccounted() throws Exception {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(BUDGET, BUDGET);
		try (var ledger = manager.openQuery(); var registry = new OptionalMaterialization(new Object(), ledger)) {
			long baseline = manager.usedBytes();
			List<OptionalEvaluationIdentity> children = new ArrayList<>();
			AtomicInteger closes = new AtomicInteger();
			Object operator = new Object();
			try {
				for (int i = 0; i < ENTRIES; i++) {
					OptionalEvaluationIdentity child = registry.child(registry.root());
					children.add(child);
					try (var ignored = registry.acquire(child, operator, 0L, () -> "same input", false,
							() -> resource(closes))) {
						assertThat(ignored.value()).isNotNull();
					}
				}
			} finally {
				children.forEach(OptionalEvaluationIdentity::close);
			}
			assertThat(closes).hasValue(ENTRIES);
			assertThat(registry.metrics().entries()).isZero();
			assertThat(manager.usedBytes()).as("the live registry retains the enlarged mandatory directory")
					.isGreaterThan(baseline);
		}
		assertThat(manager.usedBytes()).isZero();
	}

	@Test
	void evictedReusableEntriesKeepTheirRetainedDirectoryCapacityAccounted() throws Exception {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(BUDGET, BUDGET);
		try (var ledger = manager.openQuery(); var registry = new OptionalMaterialization(new Object(), ledger)) {
			long baseline = manager.usedBytes();
			AtomicInteger closes = new AtomicInteger();
			Object operator = new Object();
			for (int i = 0; i < ENTRIES; i++) {
				int key = i;
				try (var ignored = registry.acquire(registry.root(), operator, 0L, () -> key, true,
						() -> resource(closes))) {
					assertThat(ignored.value()).isNotNull();
				}
			}
			assertThatThrownBy(() -> registry.acquire(registry.root(), operator, BUDGET, () -> "cannot fit", true,
					() -> resource(closes))).isInstanceOf(QueryEvaluationException.class);
			assertThat(closes).hasValue(ENTRIES);
			assertThat(registry.metrics().entries()).isZero();
			assertThat(manager.usedBytes()).as("the live registry retains the enlarged reusable directory")
					.isGreaterThan(baseline);
		}
		assertThat(manager.usedBytes()).isZero();
	}

	private static AutoCloseable resource(AtomicInteger closes) {
		return closes::incrementAndGet;
	}
}
